    if wt <= 0.0:
        return zero

    w = np.zeros(n, dtype=float)
    w[long_sel] = wt
    w[short_sel] = -wt

    w = np.nan_to_num(w, nan=0.0, posinf=0.0, neginf=0.0)
    w = np.clip(w, -0.02, 0.02)

    gross = np.abs(w).sum()
    if gross > 1.0:
        w = w * (1.0 / gross)

    return pd.Series(w, index=tickers, dtype=float)

import numpy as np
import pandas as pd
import math


def _get_df(history, names):
    for name in names:
        obj = history.get(name)
        if isinstance(obj, pd.DataFrame):
            return obj
    return None


def generate_weights(history, universe):
    universe = pd.Index(universe)
    if len(universe) == 0:
        return pd.Series(dtype=float)

    price = _get_df(history, ['adjusted_close', 'close'])
    if price is None:
        return pd.Series(0.0, index=universe)

    price = price.reindex(columns=universe).iloc[-260:]
    if price.shape[0] < 25:
        return pd.Series(0.0, index=universe)

    last = price.iloc[-1]
    cnt = price.notna().sum()
    valid = last.notna() & (last > 2.0) & (cnt >= 60)

    vol_df = _get_df(history, ['volume'])
    if vol_df is not None:
        vol_df = vol_df.reindex(columns=universe).iloc[-60:]
        vmed = vol_df.tail(20).median()
        valid = valid & (vmed > 100000)

    elig_df = _get_df(history, ['eligible'])
    if elig_df is not None:
        e = elig_df.reindex(columns=universe).iloc[-1]
        valid = valid & e.fillna(True).astype(bool)

    rets = price / price.shift(1) - 1.0
    vol = rets.tail(60).std()
    vol = vol.replace(0.0, np.nan).clip(lower=0.005)

    def form(k):
        if price.shape[0] >= k + 1:
            return price.iloc[-1] / price.iloc[-k - 1] - 1.0
        return pd.Series(np.nan, index=universe)

    ret21 = form(21)
    ret5 = form(5)

    valid = valid & ret21.notna() & (ret21 < 1.5) & (ret21 > -0.75)
    if valid.sum() < 4:
        return pd.Series(0.0, index=universe)

    m21 = ret21[valid].mean()
    m5 = ret5[valid].mean()
    z21 = (ret21 - m21) / (vol * math.sqrt(21.0))
    z5 = (ret5 - m5) / (vol * math.sqrt(5.0))

    score = -(0.8 * z21 + 0.2 * z5)
    score = score.where(valid).replace([np.inf, -np.inf], np.nan).dropna()

    if len(score) < 10:
        score = (-(0.8 * ret21 + 0.2 * ret5)).where(valid)
        score = score.replace([np.inf, -np.inf], np.nan).dropna()

    if len(score) < 2:
        return pd.Series(0.0, index=universe)

    m = len(score)
    n_side = min(50, m // 2)
    if n_side < 1:
        n_side = 1

    sorted_score = score.sort_values(ascending=False)
    long_names = sorted_score.index[:n_side]
    short_names = sorted_score.index[-n_side:]

    w = min(0.5 / n_side, 0.02)
    weights = pd.Series(0.0, index=universe)
    weights.loc[long_names] += w
    weights.loc[short_names] -= w

    net = weights.sum()
    if abs(net) > 1e-12:
        idx = weights.index[weights != 0.0]
        if len(idx) > 0:
            weights.loc[idx] -= net / len(idx)

    weights = weights.clip(-0.02, 0.02)
    gross = weights.abs().sum()
    if gross > 1.0:
        weights = weights * (1.0 / gross)

    return weights.fillna(0.0).astype(float)

import numpy as np
import pandas as pd

def generate_weights(history, universe):
    universe = pd.Index(universe)
    n = len(universe)
    if n == 0:
        return pd.Series(dtype=float)

    ac = history.get('adjusted_close')
    if ac is None:
        ac = history.get('close')
    if ac is None:
        return pd.Series(0.0, index=universe)

    cols = [t for t in universe if t in ac.columns]
    if len(cols) < 2:
        return pd.Series(0.0, index=universe)

    prices = ac.loc[:, cols].tail(300).astype(float).copy()
    if len(prices) < 25:
        return pd.Series(0.0, index=universe)

    rets = prices.pct_change(fill_method=None)
    last = prices.iloc[-1]
    vol = rets.tail(60).std(ddof=0)

    if len(prices) >= 22:
        r21 = prices.iloc[-1] / prices.iloc[-22] - 1.0
    else:
        r21 = pd.Series(np.nan, index=cols)

    if len(prices) >= 252:
        mom = prices.iloc[-22] / prices.iloc[-252] - 1.0
    elif len(prices) >= 126:
        mom = prices.iloc[-22] / prices.iloc[-126] - 1.0
    else:
        mom = pd.Series(np.nan, index=cols)

    vol_df = history.get('volume')
    if vol_df is not None:
        vcols = [t for t in cols if t in vol_df.columns]
        v = vol_df.loc[:, vcols].tail(20).astype(float)
        close_df = history.get('close')
        if close_df is not None:
            c = close_df.loc[:, vcols].tail(20).astype(float)
        else:
            c = prices.loc[:, vcols].tail(20)
        adv = (v * c).mean(skipna=True)
        adv = adv.reindex(cols)
    else:
        adv = pd.Series(np.nan, index=cols)

    eligible_df = history.get('eligible')
    if eligible_df is not None and len(eligible_df):
        erow = eligible_df.iloc[-1].reindex(cols)
        elig = erow.fillna(False).astype(bool)
    else:
        elig = pd.Series(True, index=cols)

    df = pd.DataFrame({'r21': r21, 'mom': mom, 'vol': vol, 'adv': adv, 'eligible': elig, 'last': last})
    df = df.replace([np.inf, -np.inf], np.nan)
    df = df[df['eligible'] & df['last'].notna() & df['r21'].notna() & df['vol'].notna() & (df['vol'] > 0)]

    if df['adv'].notna().sum() >= 5:
        df = df[df['adv'].notna() & (df['adv'] > 0)]
        if len(df) >= 5:
            q = df['adv'].quantile(0.20)
            df = df[df['adv'] >= q]

    if len(df) < 4:
        return pd.Series(0.0, index=universe)

    rank_rev = (-df['r21']).rank(method='average', pct=True)
    rank_mom = df['mom'].rank(method='average', pct=True).fillna(0.5)
    rank_lowvol = (-df['vol']).rank(method='average', pct=True)

    df = df.copy()
    df['score'] = 0.55 * rank_rev + 0.30 * rank_mom + 0.15 * rank_lowvol

    n_side = min(50, len(df) // 2)
    if n_side < 1:
        return pd.Series(0.0, index=universe)

    ordered = df.sort_values('score', ascending=False)
    longs = ordered.index[:n_side]
    shorts = ordered.index[-n_side:]

    side_gross = min(0.5, 0.02 * n_side)
    w = side_gross / n_side

    weights = pd.Series(0.0, index=universe)
    weights.loc[longs] = w
    weights.loc[shorts] = -w
    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0).clip(-0.02, 0.02)
    return weights.astype(float)

import numpy as np
import pandas as pd

def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    n = len(tickers)
    if n == 0:
        return pd.Series(dtype=float)
    zero = pd.Series(np.zeros(n, dtype=float), index=tickers)
    ac = history.get('adjusted_close')
    if ac is None or len(ac.index) < 5:
        return zero
    try:
        ac = ac.reindex(columns=tickers)
    except Exception:
        return zero
    dates = ac.index
    last_pos = len(dates) - 1
    signal_pos = last_pos
    if isinstance(dates, pd.DatetimeIndex) and last_pos >= 0:
        wd = dates.weekday.values
        mons = np.where(wd[:last_pos + 1] == 0)[0]
        if len(mons) > 0:
            signal_pos = mons[-1]
    L = 21
    if signal_pos < L + 1:
        return zero
    close_all = ac.values
    cur_close = close_all[last_pos]
    valid = np.isfinite(cur_close) & (cur_close > 1.0)
    elig = history.get('eligible')
    if elig is not None:
        try:
            e = elig.reindex(index=dates, columns=tickers)
            le = e.iloc[last_pos].values
            if le.dtype == bool:
                valid_e = le
            else:
                valid_e = np.array([(x is True) or (x == 1) for x in le], dtype=bool)
            if np.any(pd.notna(le)):
                valid &= valid_e
        except Exception:
            pass
    close_sig = close_all[:signal_pos + 1]
    ret = close_sig[-1] / close_sig[-1 - L] - 1.0
    valid &= np.isfinite(ret)
    vol = history.get('volume')
    if vol is not None:
        try:
            v = vol.reindex(index=dates, columns=tickers).values[:signal_pos + 1]
            if v.shape[0] >= 20:
                dv = np.nanmean(close_sig[-20:] * v[-20:], axis=0)
                valid &= np.isfinite(dv) & (dv > 0)
                if valid.sum() >= 20:
                    thresh = np.nanpercentile(dv[valid], 20)
                    valid &= dv >= thresh
        except Exception:
            pass
    idx = np.where(valid)[0]
    if len(idx) < 6:
        return zero
    raw_score = -ret[idx]
    scores = raw_score.copy()
    try:
        if close_sig.shape[0] >= 22:
            daily = close_sig[-21:] / close_sig[-22:-1] - 1.0
            vol20 = np.nanstd(daily, axis=0)
            vol20 = np.where(np.isfinite(vol20) & (vol20 > 1e-8), vol20, np.nan)
            adj = raw_score / vol20[idx]
            ok = np.isfinite(adj)
            scores = np.where(ok, adj, raw_score)
    except Exception:
        scores = raw_score
    order = np.argsort(scores)
    m = min(25, len(idx) // 2)
    if m < 1:
        return zero
    long_sel = idx[order[-m:]]
    short_sel = idx[order[:m]]
    wt = min(0.02, 0.5 / m)
    w = np.zeros(n, dtype=float)
    w[long_sel] = wt
    w[short_sel] = -wt
    w = np.nan_to_num(w, nan=0.0, posinf=0.0, neginf=0.0)
    w = np.clip(w, -0.02, 0.02)
    return pd.Series(w, index=tickers)

import numpy as np
import pandas as pd


def _zscore(s):
    s = pd.to_numeric(s, errors='coerce').replace([np.inf, -np.inf], np.nan)
    if s.notna().sum() < 2:
        return pd.Series(0.0, index=s.index)
    mu = s.mean()
    sd = s.std(ddof=0)
    if not np.isfinite(sd) or sd < 1e-12:
        return pd.Series(0.0, index=s.index)
    return (s - mu) / sd


def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    zero = pd.Series(0.0, index=tickers, dtype=float)
    if len(tickers) == 0:
        return zero

    ac = history.get('adjusted_close')
    if not isinstance(ac, pd.DataFrame):
        ac = history.get('close')
    if not isinstance(ac, pd.DataFrame) or ac.empty:
        return zero

    try:
        ac = ac.reindex(columns=tickers)
    except Exception:
        return zero

    dates = ac.index
    n = len(dates)
    if n < 70:
        return zero

    # Rebalance only at a completed month-end close.  On the month-end day
    # itself use that close; on later days hold the same target until the next
    # month-end.  This is the explicit turnover budget: one rebalance/month.
    asof = None
    try:
        last_date = dates[-1]
        nb = last_date + pd.offsets.BDay(1)
        if nb.month != last_date.month:
            asof = n - 1
    except Exception:
        pass

    if asof is None:
        for i in range(n - 2, -1, -1):
            if dates[i].month != dates[i + 1].month:
                asof = i
                break

    if asof is None or asof < 64:
        return zero

    px = ac.iloc[:asof + 1].tail(300)
    if len(px) < 64:
        return zero

    last_px = px.iloc[-1].astype(float)
    valid = last_px.notna() & np.isfinite(last_px) & (last_px > 2.0)
    cnt = px.notna().sum()
    valid = valid & (cnt >= 60)

    rets = px.pct_change(fill_method=None)
    vol60 = rets.tail(60).std(ddof=0).replace([np.inf, -np.inf], np.nan)
    valid = valid & vol60.notna() & (vol60 > 0.0)
    vol60 = vol60.clip(lower=1e-4)

    elig_df = history.get('eligible')
    if isinstance(elig_df, pd.DataFrame) and len(elig_df) > asof:
        try:
            e = elig_df.reindex(columns=tickers).iloc[asof]
            e = e.fillna(False).astype(bool)
            if e.sum() >= 10:
                valid = valid & e
        except Exception:
            pass

    vdf = history.get('volume')
    adv = pd.Series(np.nan, index=tickers)
    if isinstance(vdf, pd.DataFrame):
        try:
            v = vdf.reindex(columns=tickers).iloc[:asof + 1].tail(20)
            cdf = history.get('close')
            if not isinstance(cdf, pd.DataFrame):
                cdf = ac
            c = cdf.reindex(columns=tickers).iloc[:asof + 1].tail(20)
            if len(v) == len(c) and len(v) > 0:
                adv = (v * c).median(skipna=True)
        except Exception:
            pass

    def form(k):
        if len(px) > k:
            return px.iloc[-1].astype(float) / px.iloc[-k - 1].astype(float) - 1.0
        return pd.Series(np.nan, index=tickers)

    r21 = form(21)
    r63 = form(63)
    valid = valid & r21.notna() & r63.notna()
    valid = valid & (r21 < 1.5) & (r21 > -0.75) & (r63 < 2.0) & (r63 > -0.8)

    # Pure reversal: recent losers are expected to outperform recent winners.
    # Dividing by own volatility prevents the ranking from becoming a pure
    # high-volatility bet.
    base = -(0.70 * r21 + 0.30 * r63)
    score = base / vol60
    score = score.replace([np.inf, -np.inf], np.nan)
    valid = valid & score.notna()

    if adv.notna().sum() >= 10:
        dvv = adv.replace([np.inf, -np.inf], np.nan)
        q = dvv[valid].quantile(0.20) if valid.sum() >= 5 else dvv.quantile(0.20)
        threshold = max(250000.0, float(q) if np.isfinite(q) else 0.0)
        valid = valid & dvv.notna() & (dvv >= threshold)

    if valid.sum() < 10:
        valid = last_px.notna() & np.isfinite(last_px) & (last_px > 2.0) & score.notna()

    s = score[valid].dropna().sort_values(ascending=False)
    m = len(s)
    if m < 4:
        return zero

    n_side = min(50, m // 2)
    if n_side < 2:
        return zero

    w = min(0.02, 0.5 / float(n_side))
    longs = s.index[:n_side]
    shorts = s.index[-n_side:]

    weights = pd.Series(0.0, index=tickers, dtype=float)
    weights.loc[longs] = w
    weights.loc[shorts] = -w
    weights = weights.replace([np.inf, -np.inf], np.nan).fillna(0.0).clip(-0.02, 0.02)
    return weights.astype(float)

import numpy as np
import pandas as pd
import math


def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    n = len(tickers)
    if n == 0:
        return pd.Series(dtype=float)

    zero = pd.Series(0.0, index=tickers, dtype=float)

    ac = history.get('adjusted_close')
    if ac is None:
        ac = history.get('close')
    if ac is None:
        return zero

    try:
        ac = ac.reindex(columns=tickers)
    except Exception:
        return zero

    dates = ac.index
    if len(dates) < 70:
        return zero

    sub = ac.iloc[-260:]
    vals = sub.values.astype(float)
    last = vals[-1]

    valid = np.isfinite(last) & (last > 2.0)

    elig = history.get('eligible')
    if elig is not None:
        try:
            e = elig.reindex(index=dates, columns=tickers).iloc[-1]
            e = e.fillna(False).astype(bool).values
            valid = valid & e
        except Exception:
            pass

    vol_df = history.get('volume')
    if vol_df is not None:
        try:
            v = vol_df.reindex(index=dates, columns=tickers).iloc[-60:].values.astype(float)
            c = history.get('close')
            if c is not None:
                c = c.reindex(index=dates, columns=tickers).iloc[-60:].values.astype(float)
            else:
                c = sub.iloc[-60:].values.astype(float)
            adv = np.nanmean(c * v, axis=0)
            valid = valid & np.isfinite(adv) & (adv > 100000.0)
            if valid.sum() >= 20:
                thr = np.nanpercentile(adv[valid], 40.0)
                valid = valid & (adv >= thr)
        except Exception:
            pass

    if valid.sum() < 10:
        return zero

    ret = vals[1:] / vals[:-1] - 1.0

    if len(vals) < 22:
        return zero

    r21 = vals[-1] / vals[-22] - 1.0
    if len(vals) >= 6:
        r5 = vals[-1] / vals[-6] - 1.0
    else:
        r5 = r21.copy()
    r5 = np.where(np.isfinite(r5), r5, r21)

    win60 = min(60, ret.shape[0])
    vol60 = np.nanstd(ret[-win60:], axis=0) * math.sqrt(252.0)
    vol60 = np.where(np.isfinite(vol60) & (vol60 > 0.005), vol60, np.nan)

    valid = valid & np.isfinite(r21) & np.isfinite(r5) & np.isfinite(vol60)
    if valid.sum() < 10:
        return zero

    market_ret = np.nanmean(ret[-min(250, ret.shape[0]):], axis=1)
    market_ret = np.nan_to_num(market_ret, nan=0.0, posinf=0.0, neginf=0.0)
    mkt_level = np.cumprod(1.0 + market_ret)

    if len(mkt_level) >= 200:
        ma200 = np.nanmean(mkt_level[-200:])
    else:
        ma200 = np.nanmean(mkt_level)
    mkt_now = mkt_level[-1]

    if len(mkt_level) >= 22:
        m21 = mkt_now / mkt_level[-22] - 1.0
    else:
        m21 = np.nanmean(r21[valid])

    if len(mkt_level) >= 61:
        m60 = mkt_now / mkt_level[-61] - 1.0
    else:
        m60 = 0.0

    mvol = np.nanstd(market_ret[-min(21, len(market_ret)):]) * math.sqrt(252.0)
    if not np.isfinite(mvol) or mvol < 1e-6:
        mvol = 0.15

    disp = np.nanstd(r21[valid])
    if not np.isfinite(disp) or disp < 1e-6:
        disp = 0.10

    scale = 1.0

    scale *= np.clip(0.20 / max(mvol, 0.08), 0.20, 1.0)
    scale *= np.clip(0.22 / max(disp, 0.08), 0.30, 1.0)

    if np.isfinite(mkt_now) and np.isfinite(ma200) and mkt_now < ma200:
        scale *= 0.30

    if np.isfinite(m21):
        if m21 > 0.07:
            scale *= 0.50
        if m21 > 0.10:
            scale *= 0.0
        if m21 > 0.04 and m60 < 0.0:
            scale *= 0.30

    scale = float(np.clip(scale, 0.0, 1.0))
    if scale < 0.10:
        return zero

    idx = np.where(valid)[0]
    if len(idx) < 10:
        return zero

    mu21 = np.nanmean(r21[idx])
    mu5 = np.nanmean(r5[idx])

    z21 = (r21[idx] - mu21) / (vol60[idx] * math.sqrt(21.0))
    z5 = (r5[idx] - mu5) / (vol60[idx] * math.sqrt(5.0))
    score = -(0.70 * z21 + 0.30 * z5)

    score = np.nan_to_num(score, nan=0.0, posinf=0.0, neginf=0.0)

    order = np.argsort(score)
    m = min(30, len(idx) // 2)
    if m < 1:
        return zero

    long_sel = idx[order[-m:]]
    short_sel = idx[order[:m]]

    gross_target = 0.80 * scale
    wt = min(0.02, (gross_target / 2.0) / float(m))
    if wt <= 0.0:
        return zero

    w = np.zeros(n, dtype=float)
    w[long_sel] = wt
    w[short_sel] = -wt

    w = np.nan_to_num(w, nan=0.0, posinf=0.0, neginf=0.0)
    w = np.clip(w, -0.02, 0.02)

    gross = np.abs(w).sum()
    if gross > 1.0:
        w = w * (1.0 / gross)

    return pd.Series(w, index=tickers, dtype=float)

